  const defaults=(material='composite')=>({material,type:'single',modelId:material==='carbon'?'carbon-user-1':material==='abs'?'abs-102':'cps-102',color:'A55',carbonColorId:'carbon-user-1',carbonCode:'',width:900,height:2200,quantity:1,frame:'110',surface:'patterned',glass:'none',baseOverride:'',modelUnpriced:false,lockId:'',lockQuantity:1,extras:[],slidingPack:false,slidingPrice:'',install:'square',installOverride:'',installVat:'',customLabel:'',customAmount:'',transom:{enabled:false,width:900,height:400,frame:'80/110',fill:'none'}});
